  `idIncidentReports` int(11) NOT NULL AUTO_INCREMENT,
  `ReportNumber` varchar(30) NOT NULL,
  `DateReported` datetime DEFAULT current_timestamp(),
  `ReportedByID` int(11) DEFAULT NULL,
  `IncidentType` varchar(100) DEFAULT NULL,
  `Description` text NOT NULL,
  `Location` varchar(200) DEFAULT NULL,
  `Severity` varchar(20) DEFAULT 'Low',
  `Status` varchar(30) DEFAULT 'Open',
  `AssignedTo` varchar(100) DEFAULT NULL,
  `ResolvedDate` datetime DEFAULT NULL,
  `Remarks` text DEFAULT NULL,
  PRIMARY KEY (`idIncidentReports`),
  UNIQUE KEY `ReportNumber_UNIQUE` (`ReportNumber`),
  KEY `ReportedByID_idx` (`ReportedByID`),
  CONSTRAINT `fk_IncidentReports_ReportedByID` FOREIGN KEY (`ReportedByID`) REFERENCES `resident` (`idResident`)
