--
-- Table structure for table `resident`
--

DROP TABLE IF EXISTS `resident`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resident` (
  `idResident` int(11) NOT NULL AUTO_INCREMENT,
  `FirstName` varchar(50) NOT NULL,
  `LastName` varchar(50) NOT NULL,
  `MiddleName` varchar(50) NOT NULL,
  `DateOfBirth` date DEFAULT NULL,
  `Gender` varchar(50) DEFAULT NULL,
  `CivilStatus` varchar(20) DEFAULT 'Single',
  `Occupation` varchar(100) DEFAULT NULL,
  `ContactNumber` varchar(20) DEFAULT NULL,
  `Email` varchar(100) DEFAULT NULL,
  `Address` text DEFAULT NULL,
  `Photo` longblob DEFAULT NULL,
  `IsActive` tinyint(1) DEFAULT 1,
  `IsRegisteredVoter` tinyint(1) NOT NULL DEFAULT 0,
  `Is4PsBeneficiary` tinyint(1) NOT NULL DEFAULT 0,
  `HouseholdNumber` varchar(20) DEFAULT NULL,
  `EmergencyContactName` varchar(100) DEFAULT NULL,
  `EmergencyContactRelation` varchar(50) DEFAULT NULL,
  `EmergencyContactPhone` varchar(20) DEFAULT NULL,
  `DateRegistered` datetime DEFAULT NULL,
  `CreatedAt` datetime DEFAULT current_timestamp(),
  `PlaceOfBirth` varchar(100) DEFAULT NULL,
  `Citizenship` varchar(50) NOT NULL DEFAULT 'Filipino',
  `Height` varchar(10) DEFAULT NULL,
  `Weight` varchar(10) DEFAULT NULL,
  `TIN` varchar(20) DEFAULT NULL,
  `ICRNumber` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`idResident`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
